async def replay():
    import subprocess
    orig=subprocess.Popen
    chrome.subprocess.Popen=lambda a,**k: orig(a[:-1]+["--host-resolver-rules=MAP * 127.0.0.1:1, EXCLUDE 127.0.0.1","--disable-web-security"]+a[-1:],**k) if "--no-first-run" in a else orig(a,**k)
    c=chrome.launch(headless=False); chrome.subprocess.Popen=orig
    out={}
    async with async_playwright() as p:
        b=await p.chromium.connect_over_cdp(c.cdp_url); g=SubmitGuard(); await g.install(b.contexts[0])
        pg=b.contexts[0].pages[0]; await pg.goto(U)
        bad=[]
        for group,want in ((SUBMITS,True),(READS,False)):
            for m,u,body,_ in group:
                n,k=len(g.blocked),len(g.allowed_posts)
                ct="multipart/form-data; boundary=b" if body.startswith("--") else "application/x-www-form-urlencoded"
                await pg.evaluate("([m,u,b,c])=>fetch(u,{method:m,body:b,mode:'no-cors',headers:{'content-type':c}}).catch(e=>0)",[m,u,body,ct])
                blocked=len(g.blocked)>n; allowed=len(g.allowed_posts)>k
                if blocked!=want or allowed==want: bad.append((u[-60:],body[:40],blocked,allowed))
    await asyncio.to_thread(c.stop)
    return len(SUBMITS),len(READS),bad
def main():
    import hashlib,json
    from pathlib import Path
    P=Path("results/llm/real/guard_proof.json"); P.unlink(missing_ok=True)
    start_devsite()
    bad=unit(); rep=asyncio.run(replay()); print('replay submits',rep[0],'reads',rep[1],'wrong',rep[2]); ctl=asyncio.run(go(False)); got=asyncio.run(go(True))
    print("unit fails",bad,"control",ctl,"guarded",got)
    ok=(not bad) and (not rep[2]) and ctl[0]==10 and got[0]==0 and got[1]>=10 and got[2] and ctl[2]
    if ok:
        P.parent.mkdir(parents=True,exist_ok=True)
        P.write_text(json.dumps({"sha256":hashlib.sha256(Path("bench/llm/guard.py").read_bytes()).hexdigest(),"control_leaked":ctl[0],"guarded_leaked":got[0],"blocked":got[1],"replayed_submits_blocked":rep[0],"replayed_reads_allowed":rep[1]}))
    print("GUARD PROOF","PASS" if ok else "FAIL")
